mapper.select:
/* 마진율 등록 전 이미 등록되어있는 기간 등록 시 실행, 미등록 시 실행하지 않음*/
SELECT
	COUNT(margin_ratio_no)
FROM
	margin_ratio
WHERE
	ent_ceo_no = #{enterpriseCeoNum}
	AND period = #{period};

mapper.insert:
/* 업체별 마진율 최초 등록 (랜덤코드) */
INSERT INTO margin_ratio
(margin_ratio_no, ent_ceo_no, ent_emp_id, period, margin_ratio, register_date, revision_date, use_status)
VALUES(#{marginRatioNum}, #{enterpriseCeoNum}, #{enterpriseEmployeeId}, #{period}, #{marginRatio}, NOW(), NOW(), '사용중');

mapper.update:
/* 업체별 마진율 사용유무 설정 (사실상 삭제 기능도 포함) */ UPDATE margin_ratio SET
use_status = '사용불가',
use_status = '사용중',
revision_date = NOW() WHERE margin_ratio_no = #{marginRatioNum};

/* 업체별 설정한 마진율 변경 */
UPDATE margin_ratio
SET
    margin_ratio = #{marginRatio},
    revision_date = NOW()
WHERE
    ent_ceo_no = #{enterpriseCeoNum}
    AND period = #{period};
